        <Message
            at="2025-12-17T05:06:16.983616Z"
        >
            <Origin>019b2ab3-7464-777a-ae26-64c263be6863</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Paragraph>Let me check what's actually available for Windows:</Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    jpegoptim
                </Word> - simple, effective for JPGs:
            </Paragraph>
            <CodeBox
                language="powershell"
            >
                {`choco install jpegoptim`}
            </CodeBox>
            <Paragraph>
                <Word>
                    <Bold />
                    mozjpeg
                </Word> - Mozilla's encoder, excellent for text screenshots:
            </Paragraph>
            <CodeBox
                language="powershell"
            >
                {`choco install mozjpeg`}
            </CodeBox>
            <Paragraph>If you have Chocolatey, mozjpeg is the best. After install:</Paragraph>
            <CodeBox
                language="powershell"
            >
                {`${''}Get-ChildItem screenshots\\*.jpg | ForEach-Object { cjpeg -quality 55 -optimize "$_" > "screenshots\\temp.jpg"; Move-Item "screenshots\\temp.jpg" $_ -Force; Write-Host "$($_.Name): $([math]::Round($_.Length/1KB))KB" }`}
            </CodeBox>
            <Paragraph>
                Or <Word>
                    <Bold />
                    jpegoptim
                </Word> is simpler:
            </Paragraph>
            <CodeBox
                language="powershell"
            >
                {`jpegoptim --max=55 --strip-all screenshots\\*.jpg`}
            </CodeBox>
            <Paragraph>Do you have Chocolatey installed? If not:</Paragraph>
            <CodeBox
                language="powershell"
            >
                {`${''}Set-ExecutionPolicy Bypass -Scope Process -Force; [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol -bor 3072; iex ((New-Object System.Net.WebClient).DownloadString('https://community.chocolatey.org/install.ps1'))`}
            </CodeBox>
            <Paragraph>
                Then <Word>
                    <Verbatim />
                    choco install jpegoptim
                </Word> and run the one-liner.
            </Paragraph>
        </Message>
