            <Paragraph>
                Doug: This is me asking GPT for some standard formatting advice. I am not sure how seriously to take all of
                this. Don't break anything but if it's easy or GPT says mandatory, do it. I am concerned that the TOC looks
                strange, but its not that bad
            </Paragraph>
